import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Use Cases","description":"","frontmatter":{},"headers":[],"relativePath":"guides/use-cases.md","filePath":"guides/use-cases.md","lastUpdated":1790952322000}'),r={name:"guides/use-cases.md"};function n(i,e,h,l,c,p){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h1><p>Ready-to-follow scenarios that combine multiple Memoh features to solve real problems.</p><p>A good bot <strong>owns a repeatable outcome</strong>, not a loose category of questions. Each scenario below states what the bot owns, which features it uses, and a starting prompt you can send as-is. Every example starts with read-only work — check the output first, then grant more.</p><h2 id="morning-digest" tabindex="-1">Morning Digest <a class="header-anchor" href="#morning-digest" aria-label="Permalink to &quot;Morning Digest&quot;">​</a></h2><p><strong>Owns:</strong> one message that starts your workday with everything you care about.</p><p><strong>Uses:</strong> <a href="./schedule.html">Scheduled Tasks</a> · <a href="./../integrations/providers/web-search.html">Web Search Providers</a> · <a href="./../integrations/channels/">Platforms</a></p><p><strong>Start with:</strong></p><blockquote><p>Every weekday at 8am, summarize releases and notable issues from the repositories I follow over the last 24 hours, add today&#39;s weather, and send it to me as one digest. Cite a source for every item; if something is uncertain, say so instead of guessing.</p></blockquote><p>The bot has a <code>schedule</code> tool: describe the timing in plain language and it registers the cron entry itself. Cap the first runs with <strong>Max Calls</strong> until the format looks right.</p><h2 id="release-watch" tabindex="-1">Release Watch <a class="header-anchor" href="#release-watch" aria-label="Permalink to &quot;Release Watch&quot;">​</a></h2><p><strong>Owns:</strong> an external change you are waiting for, reported the moment it happens.</p><p><strong>Uses:</strong> <a href="./schedule.html">Scheduled Tasks</a> · <a href="./container.html">Workspace</a> · <a href="./../integrations/channels/">Platforms</a></p><p><strong>Start with:</strong></p><blockquote><p>Watch this project&#39;s releases page and check every 30 minutes. When a new version ships, write the changes up as Markdown in your workspace and ping me once on Telegram. Organize only — do not run any upgrade or install anything.</p></blockquote><p>&quot;It&#39;s there even when you&#39;re not&quot; is schedules plus proactive messages: check on a timer, speak only when something changed. The same pattern watches prices, stock, or document updates.</p><h2 id="group-on-call-assistant" tabindex="-1">Group On-Call Assistant <a class="header-anchor" href="#group-on-call-assistant" aria-label="Permalink to &quot;Group On-Call Assistant&quot;">​</a></h2><p><strong>Owns:</strong> secretary duty in a team group: answers when mentioned and posts a daily recap.</p><p><strong>Uses:</strong> <a href="./../integrations/channels/">Platforms</a> · <a href="./sessions.html">Sessions</a> · <a href="./access.html">Access Control</a> · <a href="./schedule.html">Scheduled Tasks</a></p><p><strong>Start with:</strong></p><blockquote><p>Once you join this group: when someone mentions you, summarize the day&#39;s discussion and open items. Every day at 6pm, post a recap organized as decisions / to-dos / open questions. Post only in this group — never message anyone privately.</p></blockquote><p>Use the &quot;group only&quot; <a href="./access.html">Access Control</a> preset to fence its territory. In discuss sessions the bot decides for itself whether it has anything worth saying, so it will not flood the channel.</p><h2 id="a-living-spreadsheet" tabindex="-1">A Living Spreadsheet <a class="header-anchor" href="#a-living-spreadsheet" aria-label="Permalink to &quot;A Living Spreadsheet&quot;">​</a></h2><p><strong>Owns:</strong> one data file that the bot creates, updates on schedule, and reports changes to first.</p><p><strong>Uses:</strong> <a href="./container.html">Workspace</a> · <a href="./files.html">Files</a> · <a href="./schedule.html">Scheduled Tasks</a></p><p><strong>Start with:</strong></p><blockquote><p>Create a competitor pricing sheet (CSV) in your workspace. Check each vendor&#39;s site every morning and append any changes to the sheet; message me first if a price drops. Maintain this file only — do not send anything to anyone else.</p></blockquote><p>The workspace is a real filesystem with a terminal (Python, Node.js, and uv preinstalled), so cleaning CSVs, running scripts, and generating reports all happen in place. Browse the output any time under <strong>Files</strong>.</p><h2 id="screen-work-behind-logins" tabindex="-1">Screen Work Behind Logins <a class="header-anchor" href="#screen-work-behind-logins" aria-label="Permalink to &quot;Screen Work Behind Logins&quot;">​</a></h2><p><strong>Owns:</strong> web tasks that need eyes on a screen: console checks, form flows, OAuth.</p><p><strong>Uses:</strong> <a href="./browser-computer-use.html">Browser / Computer Use</a> · <a href="./container.html">Workspace</a> (visible desktop)</p><p><strong>Start with:</strong></p><blockquote><p>Open our admin console and verify the configuration against the checklist I give you, saving a screenshot of each item into the workspace. If you hit a login, a CAPTCHA, or anything you are unsure about, stop and wait for me to take over the desktop; continue after I hand it back. Read-only throughout — change no settings.</p></blockquote><p>The visible desktop works both ways: watch it work in the desktop pane, or take over the keyboard to type a password, then hand control back. The browser session stays in the workspace, so the next task is already signed in.</p><h2 id="build-and-preview-in-the-cloud" tabindex="-1">Build and Preview in the Cloud <a class="header-anchor" href="#build-and-preview-in-the-cloud" aria-label="Permalink to &quot;Build and Preview in the Cloud&quot;">​</a></h2><p><strong>Owns:</strong> a small project built in its own workspace, running where you can see it.</p><p><strong>Uses:</strong> <a href="./acp.html">Agents / ACP</a> · <a href="./container.html">Workspace</a> · <a href="./skills.html">Skills</a></p><p><strong>Start with:</strong></p><blockquote><p>Build a reading-list web page in your workspace: add items, mark them finished, filter by theme. When it works, start the dev server and tell me how to preview it. Commit every change locally with git — do not push to any remote.</p></blockquote><p>Prefer Claude Code or Codex? Attach your own subscription on the bot&#39;s <strong>Agent</strong> tab; it keeps working in the same workspace, on the same files.</p><h2 id="an-assistant-that-remembers" tabindex="-1">An Assistant That Remembers <a class="header-anchor" href="#an-assistant-that-remembers" aria-label="Permalink to &quot;An Assistant That Remembers&quot;">​</a></h2><p><strong>Owns:</strong> your preferences and project state, carried across sessions and platforms.</p><p><strong>Uses:</strong> <a href="./memory.html">Memory</a> · <a href="./../integrations/channels/">Platforms</a> · <a href="./schedule.html">Scheduled Tasks</a></p><p><strong>Start with:</strong></p><blockquote><p>Remember these preferences: mornings are for deep work, meetings go in the afternoon, and the weekly report is due Friday before end of day. From now on, check memory before scheduling reminders or writing summaries; if a preference is unclear, ask me instead of guessing.</p></blockquote><p>With a <a href="./../integrations/providers/memory/builtin.html">memory provider</a> configured, &quot;whatever happened with that PR?&quot; is a question it can just answer. When memories pile up, run <strong>Compact</strong> to merge and dedupe.</p><hr><h2 id="from-example-to-routine" tabindex="-1">From Example to Routine <a class="header-anchor" href="#from-example-to-routine" aria-label="Permalink to &quot;From Example to Routine&quot;">​</a></h2><ol><li><strong>Start read-only.</strong> Let it read and prepare; review a few outputs before granting writes or execution.</li><li><strong>Put constraints in the instructions.</strong> Outcome, sources, constraints, format, checkpoints — spell out all five (see <a href="./quick-start.html">Quick Start</a>).</li><li><strong>Save repeated flows as <a href="./skills.html">Skills</a>.</strong> One sentence should invoke the whole routine.</li><li><strong>Add a <a href="./schedule.html">Schedule</a> only once the flow is stable.</strong> Trial-run with Max Calls first.</li><li><strong>Keep writes and external actions behind approval,</strong> even after the routine feels safe.</li><li><strong>Fence who can command it with <a href="./access.html">Access Control</a></strong> — especially bots that join group chats.</li><li><strong>Let <a href="./memory.html">Memory</a> hold your preferences.</strong> A correction made once should stick.</li></ol>',48)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
